+import { fetchNextJob, ackJob, nackJob } from "./api.ts";
+
+export const runServer = async (port: number = 3000): Promise<void> => {
+  const handleRequest = async (req: Request): Promise<Response> => {
+    const url = new URL(req.url);
+
+    if (url.pathname === "/jobs/next" && req.method === "GET") {
+      const job = await fetchNextJob();
+      if (job === null) {
+        return new Response(JSON.stringify({ job: null }), {
+          status: 204,
+          headers: { "content-type": "application/json" },
+        });
+      }
+      return new Response(JSON.stringify(job), {
+        status: 200,
+        headers: { "content-type": "application/json" },
+      });
+    }
+
+    if (url.pathname === "/jobs/ack" && req.method === "POST") {
+      const body = await req.json() as { id: string };
+      await ackJob(body.id);
+      return new Response(JSON.stringify({ ok: true }), {
+        status: 200,
+        headers: { "content-type": "application/json" },
+      });
+    }
+
+    if (url.pathname === "/jobs/nack" && req.method === "POST") {
+      const body = await req.json() as { id: string };
+      await nackJob(body.id);
+      return new Response(JSON.stringify({ ok: true }), {
+        status: 200,
+        headers: { "content-type": "application/json" },
+      });
+    }
+
+    return new Response(JSON.stringify({ error: "Not found" }), {
+      status: 404,
+      headers: { "content-type": "application/json" },
+    });
+  };
+
+  const server = Deno.serve({ port }, handleRequest);
+  console.log(`Jobs API listening on port ${port}`);
+  await server.finished;
+};
